//! Declarative cleanup rules. A rule says: a directory with this name, inside
//! a project of these ecosystems, is (safe | review) to remove because it is
//! regenerated by this command.
//!
//! Rules only ever match **directories**. Files are never removed by rules.

use crate::model::{ArtifactCategory, Safety, Stack};
use serde::{Deserialize, Serialize};

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct CleanupRule {
    /// Unique id, e.g. `node_modules` or `rust-target`.
    pub id: String,
    /// Directory name to match. Supports `*` wildcards (`*.egg-info`).
    pub pattern: String,
    /// Ecosystems this rule applies to. Empty means every project.
    #[serde(default)]
    pub ecosystems: Vec<Stack>,
    pub safety: Safety,
    #[serde(default = "default_true")]
    pub regeneratable: bool,
    #[serde(default = "default_category")]
    pub category: ArtifactCategory,
    /// One sentence answering "why can this be removed?".
    #[serde(default)]
    pub explanation: String,
    /// Command that recreates the directory, when there is one.
    #[serde(default)]
    pub restore_hint: Option<String>,
    #[serde(default)]
    pub builtin: bool,
}

fn default_true() -> bool {
    true
}

fn default_category() -> ArtifactCategory {
    ArtifactCategory::Other
}

impl CleanupRule {
    fn new(
        id: &str,
        pattern: &str,
        ecosystems: &[Stack],
        safety: Safety,
        category: ArtifactCategory,
        explanation: &str,
        restore_hint: Option<&str>,
    ) -> Self {
        CleanupRule {
            id: id.to_string(),
            pattern: pattern.to_string(),
            ecosystems: ecosystems.to_vec(),
            safety,
            regeneratable: true,
            category,
            explanation: explanation.to_string(),
            restore_hint: restore_hint.map(str::to_string),
            builtin: true,
        }
    }

    pub fn matches_name(&self, name: &str) -> bool {
        glob_match(&self.pattern, name)
    }

    pub fn applies_to(&self, stacks: &[Stack]) -> bool {
        self.ecosystems.is_empty() || self.ecosystems.iter().any(|e| stacks.contains(e))
    }
}

/// The active set of rules: built-ins plus user-defined ones.
#[derive(Debug, Clone)]
pub struct RuleSet {
    rules: Vec<CleanupRule>,
    /// User-defined protected name patterns, on top of [`PROTECTED_PATTERNS`].
    extra_protected: Vec<String>,
}

impl Default for RuleSet {
    fn default() -> Self {
        RuleSet::builtin()
    }
}

impl RuleSet {
    pub fn builtin() -> Self {
        RuleSet {
            rules: builtin_rules(),
            extra_protected: Vec::new(),
        }
    }

    /// Built-in rules plus custom ones. Custom rules take precedence when both
    /// match the same directory in the same ecosystem. `protected_patterns`
    /// are extra names that must never be treated as artifacts.
    pub fn with_custom(custom: &[CleanupRule], protected_patterns: &[String]) -> Self {
        let extra_protected: Vec<String> = protected_patterns
            .iter()
            .map(|p| p.trim().to_string())
            .filter(|p| !p.is_empty())
            .collect();
        let is_protected = |name: &str| {
            is_protected_name(name) || extra_protected.iter().any(|p| glob_match(p, name))
        };
        let mut rules: Vec<CleanupRule> = custom
            .iter()
            .filter(|r| !r.pattern.trim().is_empty() && !is_protected(&r.pattern))
            .cloned()
            .map(|mut r| {
                r.builtin = false;
                r
            })
            .collect();
        rules.extend(builtin_rules());
        RuleSet {
            rules,
            extra_protected,
        }
    }

    /// Built-in protected patterns plus the user's own.
    pub fn is_protected(&self, name: &str) -> bool {
        is_protected_name(name) || self.extra_protected.iter().any(|p| glob_match(p, name))
    }

    pub fn rules(&self) -> &[CleanupRule] {
        &self.rules
    }

    pub fn find(&self, id: &str) -> Option<&CleanupRule> {
        self.rules.iter().find(|r| r.id == id)
    }

    /// True when a directory name matches *any* rule. Project discovery never
    /// descends into such directories: real projects do not live inside
    /// `node_modules/` or `target/`.
    pub fn is_barrier(&self, name: &str) -> bool {
        self.rules.iter().any(|r| r.matches_name(name))
    }

    /// Find the rule that applies to a directory inside a project with the
    /// given stacks. Ecosystem-specific rules win over generic ones.
    pub fn match_for(&self, name: &str, stacks: &[Stack]) -> Option<&CleanupRule> {
        if self.is_protected(name) {
            return None;
        }
        let mut generic: Option<&CleanupRule> = None;
        for rule in &self.rules {
            if !rule.matches_name(name) {
                continue;
            }
            if rule.ecosystems.is_empty() {
                generic.get_or_insert(rule);
                continue;
            }
            if rule.applies_to(stacks) {
                return Some(rule);
            }
        }
        generic
    }
}

