/// A directory that a candidate rule would match, for previews in Settings.
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct RuleMatch {
    pub project_name: String,
    pub project_path: std::path::PathBuf,
    pub path: std::path::PathBuf,
    pub relative_path: String,
    pub bytes: u64,
    pub file_count: u64,
}

/// Find directories in the scanned projects that `pattern` would match if
/// it were a rule for `ecosystems` (empty = every project). Existing
/// artifacts, nested projects and protected names are skipped, the walk is
/// depth-limited, and at most `limit` matches are measured.
pub fn preview_matches(
    projects: &[crate::model::Project],
    pattern: &str,
    ecosystems: &[Stack],
    limit: usize,
    cancel: &std::sync::atomic::AtomicBool,
) -> Vec<RuleMatch> {
    use crate::scanner::size::{measure_tree, relative};
    use crate::scanner::traversal::is_default_ignored;
    use std::sync::atomic::Ordering;
    const MAX_DEPTH: usize = 5;
    let pattern = pattern.trim();
    if pattern.is_empty() || is_protected_name(pattern) {
        return Vec::new();
    }
    let project_paths: std::collections::HashSet<&std::path::Path> =
        projects.iter().map(|p| p.path.as_path()).collect();
    let mut out = Vec::new();
    'projects: for project in projects {
        if !ecosystems.is_empty() && !ecosystems.iter().any(|e| project.stacks.contains(e)) {
            continue;
        }
        let artifact_paths: std::collections::HashSet<&std::path::Path> =
            project.artifacts.iter().map(|a| a.path.as_path()).collect();
        let mut stack = vec![(project.path.clone(), 0usize)];
        while let Some((dir, depth)) = stack.pop() {
            if cancel.load(Ordering::Relaxed) {
                break 'projects;
            }
            let Ok(entries) = std::fs::read_dir(&dir) else {
                continue;
            };
            for entry in entries.flatten() {
                let Ok(ft) = entry.file_type() else { continue };
                if !ft.is_dir() || ft.is_symlink() {
                    continue;
                }
                let name = entry.file_name().to_string_lossy().into_owned();
                let path = entry.path();
                if is_default_ignored(&name)
                    || artifact_paths.contains(path.as_path())
                    || project_paths.contains(path.as_path())
                {
                    continue;
                }
                if glob_match(pattern, &name) && !is_protected_name(&name) {
                    let size = measure_tree(&path, cancel);
                    out.push(RuleMatch {
                        project_name: project.name.clone(),
                        project_path: project.path.clone(),
                        relative_path: relative(&project.path, &path),
                        path,
                        bytes: size.bytes,
                        file_count: size.files,
                    });
                    if out.len() >= limit {
                        break 'projects;
                    }
                    continue;
                }
                if depth + 1 < MAX_DEPTH {
                    stack.push((path, depth + 1));
                }
            }
        }
    }
    out.sort_by_key(|m| std::cmp::Reverse(m.bytes));
    out
}

/// Names that are never treated as artifacts, whatever the rules say.
/// Simple globs: `*` matches any run of characters.
pub const PROTECTED_PATTERNS: &[&str] = &[
    "src",
    "app",
    "pages",
    "public",
    "assets",
    "uploads",
    "data",
    "migrations",
    ".git",
    ".env",
    ".env.*",
    "*.db",
    "*.sqlite",
    "*.sqlite3",
    "README*",
    "package.json",
    "package-lock.json",
    "npm-shrinkwrap.json",
    "yarn.lock",
    "pnpm-lock.yaml",
    "bun.lock",
    "bun.lockb",
    "Cargo.toml",
    "Cargo.lock",
    "pyproject.toml",
    "requirements.txt",
    "Pipfile",
    "Pipfile.lock",
    "poetry.lock",
    "uv.lock",
    "go.mod",
    "go.sum",
    "Gemfile",
    "Gemfile.lock",
    "composer.json",
    "composer.lock",
    "pubspec.yaml",
    "pubspec.lock",
    "Podfile",
    "Podfile.lock",
];

pub fn is_protected_name(name: &str) -> bool {
    PROTECTED_PATTERNS.iter().any(|p| glob_match(p, name))
}

/// Minimal glob matcher supporting `*` (any run of characters, including
/// none). Case-sensitive on purpose: rules name directories exactly.
pub fn glob_match(pattern: &str, name: &str) -> bool {
    fn go(p: &[u8], n: &[u8]) -> bool {
        match p.first() {
            None => n.is_empty(),
            Some(b'*') => {
                let rest = &p[1..];
                (0..=n.len()).any(|i| go(rest, &n[i..]))
            }
            Some(&c) => n.first() == Some(&c) && go(&p[1..], &n[1..]),
        }
    }
    go(pattern.as_bytes(), name.as_bytes())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn glob_matching() {
        assert!(glob_match("node_modules", "node_modules"));
        assert!(!glob_match("node_modules", "node_modules2"));
        assert!(glob_match("*.egg-info", "pointsy.egg-info"));
        assert!(glob_match(".env.*", ".env.local"));
        assert!(!glob_match(".env.*", ".env"));
        assert!(glob_match("README*", "README.md"));
        assert!(glob_match("*", "anything"));
    }

    #[test]
    fn ecosystem_specific_rules_win() {
        let rules = RuleSet::builtin();
        let rust = rules.match_for("target", &[Stack::Rust]).unwrap();
        assert_eq!(rust.category, ArtifactCategory::RustTarget);
        let maven = rules.match_for("target", &[Stack::Maven]).unwrap();
        assert_eq!(maven.category, ArtifactCategory::BuildArtifacts);
        // `target` in a Node-only project is not an artifact.
        assert!(rules.match_for("target", &[Stack::Node]).is_none());
        // Generic `.cache` applies everywhere.
        assert!(rules.match_for(".cache", &[Stack::Go]).is_some());
    }

    #[test]
    fn protected_names_never_match() {
        let custom = vec![CleanupRule {
            id: "evil".into(),
            pattern: "src".into(),
            ecosystems: vec![],
            safety: Safety::Safe,
            regeneratable: true,
            category: ArtifactCategory::Other,
            explanation: String::new(),
            restore_hint: None,
            builtin: false,
        }];
        let rules = RuleSet::with_custom(&custom, &[]);
        assert!(rules.match_for("src", &[Stack::Node]).is_none());
        assert!(rules.find("evil").is_none());
        assert!(is_protected_name(".env.production"));
        assert!(is_protected_name("app.sqlite"));
        assert!(!is_protected_name("node_modules"));
    }

    #[test]
    fn custom_rules_apply() {
        let custom = vec![CleanupRule {
            id: "storybook-cache".into(),
            pattern: ".storybook-cache".into(),
            ecosystems: vec![],
            safety: Safety::Safe,
            regeneratable: true,
            category: ArtifactCategory::Caches,
            explanation: "Storybook cache".into(),
            restore_hint: None,
            builtin: false,
        }];
        let rules = RuleSet::with_custom(&custom, &["generated-*".to_string()]);
        assert!(rules.is_protected("generated-sdk"));
        assert!(rules
            .match_for(".storybook-cache", &[Stack::Node])
            .is_some());
        assert!(rules.is_barrier(".storybook-cache"));
    }
}
